window.CODE_INDEX = {"classes":{"LinkPreviewDialog":{"appearsIn":[["article","h-widgets","Screen \u00b7 view composition"],["places","h-classes","Logic \u00b7 class diagram"],["places","h-sequence","Pan the map and open a place \u00b7 sequence"]],"code":"class LinkPreviewDialog : ExtendedBottomSheetDialogFragment(), LinkPreviewErrorView.Callback, DialogInterface.OnDismissListener {\n    interface LoadPageCallback {\n        fun onLinkPreviewLoadPage(title: PageTitle, entry: HistoryEntry, inNewTab: Boolean)\n    }\n\n    interface DismissCallback {\n        fun onLinkPreviewDismiss()\n    }\n\n    private var _binding: DialogLinkPreviewBinding? = null\n    private val binding get() = _binding!!\n\n    private val loadPageCallback get() = getCallback(this, LoadPageCallback::class.java)\n    private val dismissCallback get() = getCallback(this, DismissCallback::class.java)\n\n    private var articleLinkPreviewInteractionEvent: ArticleLinkPreviewInteractionEvent? = null\n    private var overlayView: LinkPreviewOverlayView? = null\n    private var navigateSuccess = false\n    private val viewModel: LinkPreviewViewModel by viewModels()\n\n    private val menuListener = PopupMenu.OnMenuItemClickListener { item ->\n        return@OnMenuItemClickListener when (item.itemId) {\n            R.id.menu_link_preview_add_to_list -> {\n                showSaveArticleSheet()\n                true\n            }\n            R.id.menu_link_preview_share_page -> {\n                ShareUtil.shareText(requireContext(), viewModel.pageTitle)\n                true\n            }\n            R.id.menu_link_preview_watch -> {\n                sendPlacesEvent(\"watch_click\", \"detail_overflow_menu\")\n                viewModel.watchOrUnwatch(viewModel.isWatched)\n                true\n            }\n            R.id.menu_link_preview_open_in_new_tab -> {\n                sendPlacesEvent(\"new_tab_click\", \"detail_overflow_menu\")\n                goToLinkedPage(true)\n                true\n            }\n            R.id.menu_link_preview_copy_link -> {\n                sendPlacesEvent(\"copy_link_click\", \"detail_overflow_menu\")\n                ClipboardUtil.setPlainText(requireActivity(), text = viewModel.pageTitle.uri)\n                FeedbackUtil.showMessage(requireActivity(), R.string.address_copied)\n                dismiss()\n                true\n            }\n            R.id.menu_link_preview_view_on_map -> {\n                PlacesEvent.logAction(\"places_click\", \"article_preview_more_menu\")\n                viewModel.location?.let {\n                    startActivity(PlacesActivity.newIntent(requireContext(), viewModel.pageTitle, it))\n                }\n                dismiss()\n                true\n            }\n            R.id.menu_link_preview_get_directions -> {\n                sendPlacesEvent(\"directions_click\", \"detail_overflow_menu\")\n                viewModel.location?.let {\n                    GeoUtil.sendGeoIntent(requireActivity(), it, StringUtil.fromHtml(viewModel.pageTitle.displayText).toString())\n                }\n                true\n            }\n            else -> false\n        }\n    }\n\n    private fun sendPlacesEvent(action: String, activeInterface: String) {\n        if (viewModel.historyEntry.source == HistoryEntry.SOURCE_PLACES) {\n            PlacesEvent.logAction(action, activeInterface)\n        }\n    }\n\n    private val galleryViewListener = GalleryViewListener { view, thumbUrl, imageName ->\n        var options: ActivityOptionsCompat? = null\n        view.drawable?.let {\n            val hitInfo = JavaScriptActionHandler.ImageHitInfo(0f, 0f, it.intrinsicWidth.toFloat(), it.intrinsicHeight.toFloat(), thumbUrl)\n            GalleryActivity.setTransitionInfo(hitInfo)\n            view.transitionName = requireActivity().getString(R.string.transition_page_gallery)\n            options = ActivityOptionsCompat.makeSceneTransitionAnimation(requireActivity(), view, requireActivity().getString(R.string.transition_page_gallery))\n        }\n        requestGalleryLauncher.launch(GalleryActivity.newIntent(requireContext(), viewModel.pageTitle,\n            imageName, viewModel.pageTitle.wikiSite), options)\n    }\n\n    private val requestGalleryLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == GalleryActivity.ACTIVITY_RESULT_PAGE_SELECTED && it.data != null) {\n            startActivity(it.data!!)\n        }\n    }\n\n    private val requestStubArticleEditLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == EditHandler.RESULT_REFRESH_PAGE) {\n            overlayView?.let { overlay ->\n                FeedbackUtil.makeSnackbar(overlay.rootView, getString(R.string.stub_article_edit_saved_successfully))\n                    .setAnchorView(overlay.secondaryButtonView).show()\n            }\n        }\n    }\n\n    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {\n        _binding = DialogLinkPreviewBinding.inflate(inflater, container, false)\n        binding.linkPreviewToolbar.setOnClickListener { goToLinkedPage(false) }\n        binding.linkPreviewOverflowButton.setOnClickListener {\n            setupOverflowMenu()\n        }\n        binding.linkPreviewEditButton.setOnClickListener {\n            viewModel.pageTitle.run {\n                requestStubArticleEditLauncher.launch(EditSectionActivity.newIntent(requireContext(), -1, null, this, Constants.InvokeSource.LINK_PREVIEW_MENU, null))\n            }\n        }\n        binding.root.setLayoutDirectionByLang(viewModel.pageTitle.wikiSite.languageCode)\n\n        lifecycleScope.launch {\n            repeatOnLifecycle(Lifecycle.State.CREATED) {\n                viewModel.uiState.collect {\n                    when (it) {\n                        is LinkPreviewViewState.Loading -> {\n                            binding.linkPreviewProgress.visibility = View.VISIBLE\n                        }\n                        is LinkPreviewViewState.Error -> {\n                            renderErrorState(it.throwable)\n                        }\n                        is LinkPreviewViewState.Content -> {\n                            renderContentState(it.data)\n                        }\n                        is LinkPreviewViewState.Gallery -> {\n                            renderGalleryState(it)\n                        }\n                        is LinkPreviewViewState.Watch -> {\n                            WatchlistViewModel.showWatchlistSnackbar(requireActivity() as BaseActivity, requireActivity().supportFragmentManager, viewModel.pageTitle, it.data.first, it.data.second)\n                            dismiss()\n                        }\n                        is LinkPreviewViewState.Completed -> {\n                            binding.linkPreviewProgress.visibility = View.GONE\n                        }\n                    }\n                }\n            }\n        }\n        return binding.root\n    }\n\n    private fun setupOverflowMenu() {\n        val popupMenu = PopupMenu(requireActivity(), binding.linkPreviewOverflowButton)\n        popupMenu.inflate(R.menu.menu_link_preview)\n        popupMenu.menu.findItem(R.id.menu_link_preview_add_to_list).isVisible = !viewModel.fromPlaces\n        popupMenu.menu.findItem(R.id.menu_link_preview_share_page).isVisible = !viewModel.fromPlaces\n        popupMenu.menu.findItem(R.id.menu_link_preview_watch).isVisible = viewModel.fromPlaces && AccountUtil.isLoggedIn\n        popupMenu.menu.findItem(R.id.menu_link_preview_watch).title = getString(if (viewModel.isWatched) R.string.menu_page_unwatch else R.string.menu_page_watch)\n        popupMenu.menu.findItem(R.id.menu_link_preview_open_in_new_tab).isVisible = viewModel.fromPlaces\n        popupMenu.menu.findItem(R.id.menu_link_preview_view_on_map).isVisible = !viewModel.fromPlaces && viewModel.location != null\n        popupMenu.menu.findItem(R.id.menu_link_preview_get_directions).isVisible = viewModel.fromPlaces\n        popupMenu.setOnMenuItemClickListener(menuListener)\n        popupMenu.show()\n    }\n\n    private fun renderGalleryState(it: LinkPreviewViewState.Gallery) {\n        binding.linkPreviewThumbnailGallery.setGalleryList(it.data)\n        binding.linkPreviewThumbnailGallery.listener = galleryViewListener\n        binding.linkPreviewProgress.visibility = View.GONE\n    }\n\n    private fun renderContentState(summary: PageSummary) {\n        articleLinkPreviewInteractionEvent = ArticleLinkPreviewInteractionEvent(\n                viewModel.pageTitle.wikiSite.dbName(),\n                summary.pageId,\n                viewModel.historyEntry.source\n        )\n        articleLinkPreviewInteractionEvent?.logLinkClick()\n\n        binding.linkPreviewTitle.text = StringUtil.fromHtml(summary.displayTitle)\n        if (viewModel.fromPlaces) {\n            viewModel.location?.let { startLocation ->\n                viewModel.lastKnownLocation?.let { endLocation ->\n                    binding.linkPreviewDistance.isVisible = true\n                    binding.linkPreviewDistance.text = GeoUtil.getDistanceWithUnit(startLocation, endLocation, Locale.getDefault())\n                }\n            }\n        }\n        showPreview(LinkPreviewContents(summary, viewModel.pageTitle.wikiSite))\n    }\n\n    private fun renderErrorState(throwable: Throwable) {\n        L.e(throwable)\n        binding.linkPreviewTitle.text = StringUtil.fromHtml(viewModel.pageTitle.displayText)\n        showError(throwable)\n    }\n\n    override fun onResume() {\n        super.onResume()\n\n        val containerView = requireDialog().findViewById<ViewGroup>(android.R.id.content)\n        if (overlayView == null && containerView != null) {\n            LinkPreviewOverlayView(requireContext()).let {\n                overlayView = it\n                if (viewModel.fromPlaces) {\n                    val strings = requireContext().getStrings(viewModel.pageTitle, intArrayOf(R.string.link_preview_dialog_share_button, R.string.link_preview_dialog_save_button, R.string.link_preview_dialog_read_button))\n                    it.callback = OverlayViewPlacesCallback()\n                    it.setPrimaryButtonText(strings[R.string.link_preview_dialog_share_button])\n                    it.setSecondaryButtonText(strings[R.string.link_preview_dialog_save_button])\n                    it.setTertiaryButtonText(strings[R.string.link_preview_dialog_read_button])\n                } else {\n                    val strings = requireContext().getStrings(viewModel.pageTitle, intArrayOf(R.string.button_continue_to_talk_page, R.string.button_continue_to_article, R.string.menu_long_press_open_in_new_tab))\n                    it.callback = OverlayViewCallback()\n                    it.setPrimaryButtonText(strings[if (viewModel.pageTitle.namespace() === Namespace.TALK || viewModel.pageTitle.namespace() === Namespace.USER_TALK) R.string.button_continue_to_talk_page else R.string.button_continue_to_article])\n                    it.setSecondaryButtonText(strings[R.string.menu_long_press_open_in_new_tab])\n                    it.showTertiaryButton(false)\n                }\n                containerView.addView(it)\n\n                ViewCompat.setOnApplyWindowInsetsListener(it) { view, insets ->\n                    val systemWindowInsets = insets.getInsets(WindowInsetsCompat.Type.systemBars())\n                    view.updateLayoutParams<ViewGroup.MarginLayoutParams> { bottomMargin = systemWindowInsets.bottom }\n                    insets\n                }\n            }\n        }\n    }\n\n    override fun onDestroyView() {\n        binding.linkPreviewThumbnailGallery.listener = null\n        binding.linkPreviewToolbar.setOnClickListener(null)\n        binding.linkPreviewOverflowButton.setOnClickListener(null)\n        overlayView?.let {\n            it.callback = null\n            overlayView = null\n        }\n        _binding = null\n        super.onDestroyView()\n    }\n\n    override fun onDismiss(dialogInterface: DialogInterface) {\n        super.onDismiss(dialogInterface)\n        dismissCallback?.onLinkPreviewDismiss()\n        if (!navigateSuccess) {\n            articleLinkPreviewInteractionEvent?.logCancel()\n        }\n    }\n\n    override fun onAddToList() {\n        showSaveArticleSheet()\n    }\n\n    override fun onDismiss() {\n        dismiss()\n    }\n\n    private fun showSaveArticleSheet() {\n        SaveArticleSheetDialog.show(parentFragmentManager, viewModel.pageTitle)\n    }\n\n    private fun showPreview(contents: LinkPreviewContents) {\n        viewModel.loadGallery()\n        setPreviewContents(contents)\n    }\n\n    private fun showError(caught: Throwable?) {\n        binding.dialogLinkPreviewContainer.layoutTransition = null\n        binding.dialogLinkPreviewContainer.minimumHeight = 0\n        binding.linkPreviewProgress.visibility = View.GONE\n        binding.dialogLinkPreviewContentContainer.visibility = View.GONE\n        binding.dialogLinkPreviewErrorContainer.visibility = View.VISIBLE\n        binding.dialogLinkPreviewErrorContainer.callback = this\n        binding.dialogLinkPreviewErrorContainer.setError(caught, viewModel.pageTitle)\n        LinkPreviewErrorType[caught, viewModel.pageTitle].run {\n            overlayView?.let {\n                it.showSecondaryButton(false)\n                it.showTertiaryButton(false)\n                it.setPrimaryButtonText(resources.getString(buttonText))\n                it.callback = buttonAction(binding.dialogLinkPreviewErrorContainer)\n                if (this !== LinkPreviewErrorType.OFFLINE) {\n                    binding.linkPreviewToolbar.setOnClickListener(null)\n                    binding.linkPreviewOverflowButton.visibility = View.GONE\n                }\n            }\n        }\n    }\n\n    private fun setPreviewContents(contents: LinkPreviewContents) {\n        val editVisibility = contents.extract.isNullOrBlank() && contents.ns?.id == Namespace.MAIN.code()\n        binding.linkPreviewEditButton.isVisible = editVisibility\n        binding.linkPreviewThumbnailGallery.isVisible = !editVisibility\n\n        val extract = if (editVisibility) \"<i>\" + getString(R.string.link_preview_stub_placeholder_text) + \"</i>\" else contents.extract\n        binding.linkPreviewExtract.text = StringUtil.fromHtml(extract)\n\n        contents.title.thumbUrl?.let {\n            binding.linkPreviewThumbnail.visibility = View.VISIBLE\n            ViewUtil.loadImage(binding.linkPreviewThumbnail, it)\n        }\n        overlayView?.run {\n            if (!viewModel.fromPlaces) {\n                setPrimaryButtonText(\n                    requireContext().getString(\n                        viewModel.pageTitle,\n                        if (contents.isDisambiguation) R.string.button_continue_to_disambiguation\n                        else if (viewModel.pageTitle.namespace() === Namespace.TALK || viewModel.pageTitle.namespace() === Namespace.USER_TALK) R.string.button_continue_to_talk_page\n                        else R.string.button_continue_to_article\n                    )\n                )\n            } else if (viewModel.fromPlaces) {\n                setSecondaryButtonText(requireContext().getString(viewModel.pageTitle, if (viewModel.isInReadingList) R.string.link_preview_dialog_saved_button else R.string.link_preview_dialog_save_button))\n            }\n        }\n    }\n\n    private fun goToLinkedPage(inNewTab: Boolean) {\n        navigateSuccess = true\n        dialog?.dismiss()\n        loadPage(viewModel.pageTitle, viewModel.historyEntry, inNewTab)\n    }\n\n    private fun loadPage(title: PageTitle, entry: HistoryEntry, inNewTab: Boolean) {\n        loadPageCallback.let {\n            if (it != null) {\n                it.onLinkPreviewLoadPage(title, entry, inNewTab)\n            } else {\n                requireActivity().startActivity(\n                    if (inNewTab) PageActivity.newIntentForNewTab(requireContext(), entry, entry.title)\n                    else PageActivity.newIntentForCurrentTab(requireContext(), entry, entry.title, false)\n                )\n            }\n        }\n    }\n\n    private inner class OverlayViewCallback : LinkPreviewOverlayView.Callback {\n        override fun onPrimaryClick() {\n            goToLinkedPage(false)\n        }\n\n        override fun onSecondaryClick() {\n            goToLinkedPage(true)\n        }\n\n        override fun onTertiaryClick() {\n            // ignore\n        }\n    }\n\n    private inner class OverlayViewPlacesCallback : LinkPreviewOverlayView.Callback {\n        override fun onPrimaryClick() {\n            sendPlacesEvent(\"share_click\", \"detail_toolbar\")\n            ShareUtil.shareText(requireContext(), viewModel.pageTitle)\n        }\n\n        override fun onSecondaryClick() {\n            overlayView?.let {\n                sendPlacesEvent(\"save_click\", \"detail_toolbar\")\n                showSaveArticleSheet()\n            }\n        }\n\n        override fun onTertiaryClick() {\n            sendPlacesEvent(\"read_click\", \"detail_toolbar\")\n            goToLinkedPage(false)\n        }\n    }\n\n    companion object {\n        const val ARG_ENTRY = \"entry\"\n        const val ARG_LOCATION = \"location\"\n        const val ARG_LAST_KNOWN_LOCATION = \"lastKnownLocation\"\n\n        fun newInstance(entry: HistoryEntry, location: Location? = null, lastKnownLocation: Location? = null): LinkPreviewDialog {\n            return LinkPreviewDialog().apply {\n                arguments = bundleOf(\n                    ARG_ENTRY to entry,\n                    ARG_LOCATION to location,\n                    ARG_LAST_KNOWN_LOCATION to lastKnownLocation\n                )\n            }\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/page/linkpreview/LinkPreviewDialog.kt","kind":"class","line":56,"members":{"ARG_ENTRY":[415,415],"ARG_LAST_KNOWN_LOCATION":[417,417],"ARG_LOCATION":[416,416],"DismissCallback":[61,63],"LoadPageCallback":[57,59],"OverlayViewCallback":[381,393],"OverlayViewPlacesCallback":[395,412],"_binding":[65,65],"articleLinkPreviewInteractionEvent":[71,71],"binding":[66,66],"dismissCallback":[69,69],"galleryViewListener":[128,138],"goToLinkedPage":[362,366],"loadPage":[368,379],"loadPageCallback":[68,68],"menuListener":[76,120],"navigateSuccess":[73,73],"newInstance":[419,427],"onAddToList":[295,297],"onCreateView":[155,196],"onDestroyView":[275,285],"onDismiss":[287,293],"onResume":[244,273],"overlayView":[72,72],"renderContentState":[218,236],"renderErrorState":[238,242],"renderGalleryState":[212,216],"requestGalleryLauncher":[140,144],"requestStubArticleEditLauncher":[146,153],"sendPlacesEvent":[122,126],"setPreviewContents":[334,360],"setupOverflowMenu":[198,210],"showError":[312,332],"showPreview":[307,310],"showSaveArticleSheet":[303,305],"viewModel":[74,74]},"supers":["ExtendedBottomSheetDialogFragment()","LinkPreviewErrorView.Callback","DialogInterface.OnDismissListener"]},"NearbyPage":{"appearsIn":[["places","h-classes","Logic \u00b7 class diagram"]],"code":"class NearbyPage(\n    val pageId: Int,\n    val pageTitle: PageTitle,\n    val latitude: Double,\n    val longitude: Double\n) {\n    val location get() = Location(\"\").apply {\n        latitude = this@NearbyPage.latitude\n        longitude = this@NearbyPage.longitude\n    }\n}","file":"app/src/main/java/org/wikipedia/dataclient/page/NearbyPage.kt","kind":"class","line":6,"members":{"latitude":[9,9],"location":[12,15],"longitude":[10,10],"pageId":[7,7],"pageTitle":[8,8]},"supers":[]},"PlacesActivity":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["places","h-classes","Logic \u00b7 class diagram"]],"code":"class PlacesActivity : SingleFragmentActivity<PlacesFragment>() {\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        disableFitsSystemWindows()\n    }\n\n    public override fun createFragment(): PlacesFragment {\n        return PlacesFragment.newInstance(intent.parcelableExtra(Constants.ARG_TITLE), intent.parcelableExtra(EXTRA_LOCATION))\n    }\n\n    companion object {\n        const val EXTRA_LOCATION = \"location\"\n        fun newIntent(context: Context, pageTitle: PageTitle? = null, location: Location? = null): Intent {\n            return Intent(context, PlacesActivity::class.java)\n                .putExtra(Constants.ARG_TITLE, pageTitle)\n                .putExtra(EXTRA_LOCATION, location)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/places/PlacesActivity.kt","kind":"class","line":12,"members":{"EXTRA_LOCATION":[24,24],"createFragment":[19,21],"newIntent":[25,29],"onCreate":[14,17]},"shot":"shots/code/PlacesActivity.jpg","supers":["SingleFragmentActivity<PlacesFragment>()"]},"PlacesFilterActivity":{"appearsIn":[["places","h-classes","Logic \u00b7 class diagram"]],"code":"class PlacesFilterActivity : BaseActivity() {\n\n    private lateinit var binding: ActivityPlacesFiltersBinding\n    private var initLanguage: String = Prefs.placesWikiCode\n    private var filtersList = mutableListOf<String>()\n\n    val addLanguageLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        // Check if places wiki language code was deleted\n        if (!WikipediaApp.instance.languageState.appLanguageCodes.contains(Prefs.placesWikiCode)) {\n            Prefs.placesWikiCode = WikipediaApp.instance.appOrSystemLanguageCode\n        }\n        setUpRecyclerView()\n        binding.placesFiltersRecyclerView.adapter?.notifyDataSetChanged()\n    }\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        binding = ActivityPlacesFiltersBinding.inflate(layoutInflater)\n\n        setUpRecyclerView()\n        setStatusBarColor(ResourceUtil.getThemedColor(this, R.attr.background_color))\n        setNavigationBarColor(ResourceUtil.getThemedColor(this, R.attr.background_color))\n        setSupportActionBar(binding.toolbar)\n        supportActionBar?.setDisplayHomeAsUpEnabled(true)\n        setContentView(binding.root)\n    }\n\n    override fun finish() {\n        setResult(RESULT_OK, Intent()\n            .putExtra(EXTRA_LANG_CHANGED, initLanguage != Prefs.placesWikiCode))\n        super.finish()\n    }\n\n    private fun setUpRecyclerView() {\n        filtersList.clear()\n        filtersList.add(HEADER)\n        filtersList.addAll(WikipediaApp.instance.languageState.appLanguageCodes)\n        filtersList.add(FOOTER)\n        binding.placesFiltersRecyclerView.layoutManager = LinearLayoutManager(this)\n        binding.placesFiltersRecyclerView.adapter = PlacesLangListFilterAdapter(this)\n    }\n\n    private inner class PlacesLangListFilterAdapter(val context: Context) :\n        RecyclerView.Adapter<DefaultViewHolder<*>>(), PlacesFilterItemViewHolder.Callback {\n\n        override fun onCreateViewHolder(parent: ViewGroup, type: Int): DefaultViewHolder<*> {\n            return when (type) {\n                VIEW_TYPE_HEADER -> {\n                    PlacesFilterHeaderViewHolder(layoutInflater.inflate(R.layout.view_watchlist_filter_header, parent, false))\n                }\n                VIEW_TYPE_FOOTER -> {\n                    PlacesFilterFooterViewHolder(layoutInflater.inflate(R.layout.view_places_filters_footer, parent, false))\n                }\n                else -> {\n                    PlacesFilterItemViewHolder(ViewPlacesFilterItemBinding.inflate(layoutInflater), this)\n                }\n            }\n        }\n\n        override fun getItemCount(): Int {\n            return filtersList.size\n        }\n\n        override fun getItemViewType(position: Int): Int {\n            return if (filtersList[position] == HEADER) VIEW_TYPE_HEADER\n            else if (filtersList[position] == FOOTER) VIEW_TYPE_FOOTER\n            else VIEW_TYPE_ITEM\n        }\n\n        override fun onBindViewHolder(holder: DefaultViewHolder<*>, position: Int) {\n            when (holder) {\n                is PlacesFilterHeaderViewHolder -> holder.bindItem(getString(R.string.watchlist_filter_wiki_filter_header))\n                is PlacesFilterFooterViewHolder -> holder.bindItem()\n                else -> (holder as PlacesFilterItemViewHolder).bindItem(filtersList[position])\n            }\n        }\n\n        override fun onLangSelected() {\n            notifyDataSetChanged()\n        }\n    }\n\n    inner class PlacesFilterHeaderViewHolder(itemView: View) : DefaultViewHolder<View>(itemView) {\n        private val headerText = itemView.findViewById<TextView>(R.id.filter_header_title)!!\n\n        fun bindItem(filterHeader: String) {\n            headerText.setTextColor(ResourceUtil.getThemedColor(this@PlacesFilterActivity, R.attr.primary_color))\n            headerText.text = filterHeader\n        }\n    }\n    inner class PlacesFilterFooterViewHolder(itemView: View) : DefaultViewHolder<View>(itemView) {\n        fun bindItem() {\n            itemView.setOnClickListener {\n                addLanguageLauncher.launch(WikipediaLanguagesActivity.newIntent(itemView.context,\n                    Constants.InvokeSource.PLACES))\n            }\n        }\n    }\n    class PlacesFilterItemViewHolder(private val itemViewBinding: ViewPlacesFilterItemBinding, val callback: Callback) : DefaultViewHolder<View>(itemViewBinding.root) {\n        interface Callback {\n            fun onLangSelected()\n        }\n\n        fun bindItem(languageCode: String) {\n            itemViewBinding.placesFilterTitle.text = WikipediaApp.instance.languageState.getAppLanguageLocalizedName(languageCode)\n            itemViewBinding.placesFilterLangCode.setLangCode(languageCode)\n            itemViewBinding.placesFilterRadio.isVisible = languageCode == Prefs.placesWikiCode\n            itemViewBinding.root.setOnClickListener {\n                if (languageCode != Prefs.placesWikiCode) {\n                    PlacesEvent.logAction(\"filter_change_save\", \"filter_view\")\n                }\n                Prefs.placesWikiCode = languageCode\n                callback.onLangSelected()\n            }\n        }\n    }\n    companion object {\n        private const val VIEW_TYPE_HEADER = 0\n        private const val VIEW_TYPE_FOOTER = 1\n        private const val VIEW_TYPE_ITEM = 2\n        private const val HEADER = \"header\"\n        private const val FOOTER = \"footer\"\n        const val EXTRA_LANG_CHANGED = \"langChanged\"\n        fun newIntent(context: Context): Intent {\n            return Intent(context, PlacesFilterActivity::class.java)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/places/PlacesFilterActivity.kt","kind":"class","line":25,"members":{"EXTRA_LANG_CHANGED":[147,147],"FOOTER":[146,146],"HEADER":[145,145],"PlacesFilterFooterViewHolder":[115,122],"PlacesFilterHeaderViewHolder":[107,114],"PlacesFilterItemViewHolder":[123,140],"PlacesLangListFilterAdapter":[67,105],"VIEW_TYPE_FOOTER":[143,143],"VIEW_TYPE_HEADER":[142,142],"VIEW_TYPE_ITEM":[144,144],"addLanguageLauncher":[31,38],"binding":[27,27],"filtersList":[29,29],"finish":[52,56],"initLanguage":[28,28],"newIntent":[148,150],"onCreate":[40,50],"setUpRecyclerView":[58,65]},"supers":["BaseActivity()"]},"PlacesFragment":{"appearsIn":[["places","h-classes","Logic \u00b7 class diagram"],["places","h-sequence","Pan the map and open a place \u00b7 sequence"]],"code":"class PlacesFragment : Fragment(), LinkPreviewDialog.LoadPageCallback, LinkPreviewDialog.DismissCallback, MapLibreMap.OnMapClickListener {\n\n    private var _binding: FragmentPlacesBinding? = null\n    private val binding get() = _binding!!\n    private var statusBarInsets: Insets? = null\n    private var navBarInsets: Insets? = null\n\n    private val viewModel: PlacesFragmentViewModel by viewModels()\n\n    private var mapboxMap: MapLibreMap? = null\n    private var symbolManager: SymbolManager? = null\n\n    private val annotationCache = ArrayDeque<PlaceMarker>()\n    private var lastCheckedId = R.id.mapViewButton\n    private var lastLocation: Location? = null\n    private var lastLocationQueried: Location? = null\n    private var lastZoom = 15.0\n    private var lastZoomQueried = 0.0\n\n    private lateinit var markerBitmapBase: Bitmap\n    private lateinit var markerPaintSrc: Paint\n    private lateinit var markerPaintSrcIn: Paint\n    private lateinit var markerBorderPaint: Paint\n    private val markerRect = getMarkerRect()\n\n    private val searchRadius\n        get() = mapboxMap?.let {\n            latitudeDiffToMeters(it.projection.visibleRegion.latLngBounds.latitudeSpan / 2)\n        } ?: 50\n    private var magnifiedMarker: Symbol? = null\n\n    private val locationPermissionRequest = registerForActivityResult(ActivityResultContracts.RequestMultiplePermissions()) { permissions ->\n        when {\n            permissions.getOrDefault(Manifest.permission.ACCESS_FINE_LOCATION, false) ||\n            permissions.getOrDefault(Manifest.permission.ACCESS_COARSE_LOCATION, false) -> {\n                PlacesEvent.logAction(\"location_permission_granted\", \"map_view\")\n                startLocationTracking()\n                goToLocation(viewModel.location ?: getDefaultLocation())\n            }\n            else -> {\n                PlacesEvent.logAction(\"location_permission_denied\", \"map_view\")\n                FeedbackUtil.showMessage(requireActivity(), R.string.places_permissions_denied)\n            }\n        }\n    }\n\n    private val placesSearchLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == SearchActivity.RESULT_LINK_SUCCESS) {\n            val location = it.data?.parcelableExtra<Location>(PlacesActivity.EXTRA_LOCATION)!!\n            val pageTitle = it.data?.parcelableExtra<PageTitle>(SearchActivity.EXTRA_RETURN_LINK_TITLE)!!\n            viewModel.highlightedPageTitle = pageTitle\n            Prefs.placesWikiCode = pageTitle.wikiSite.languageCode\n            goToLocation(preferredLocation = location, zoom = 15.9)\n            viewModel.fetchNearbyPages(location.latitude, location.longitude, searchRadius, ITEMS_PER_REQUEST)\n        }\n    }\n\n    private val filterLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == RESULT_OK) {\n            val languageChanged = it.data?.getBooleanExtra(PlacesFilterActivity.EXTRA_LANG_CHANGED, false) ?: false\n            if (languageChanged) {\n                clearAnnotationCache()\n                viewModel.highlightedPageTitle = null\n                symbolManager?.deleteAll()\n                viewModel.fetchNearbyPages(lastLocation?.latitude ?: 0.0,\n                    lastLocation?.longitude ?: 0.0, searchRadius, ITEMS_PER_REQUEST)\n                goToLocation(lastLocation, lastZoom)\n            }\n        }\n    }\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        markerPaintSrc = getMarkerPaintSrc(requireContext())\n        markerPaintSrcIn = getMarkerPaintSrcIn()\n        markerBorderPaint = getMarkerBorderPaint(requireContext())\n        markerBitmapBase = getMarkerBitmapBase(requireContext())\n\n        MapLibre.getInstance(requireActivity().applicationContext)\n\n        HttpRequestImpl.setOkHttpClient(OkHttpConnectionFactory.client)\n\n        requireArguments().parcelable<PageTitle>(Constants.ARG_TITLE)?.let {\n            Prefs.placesWikiCode = it.wikiSite.languageCode\n        }\n    }\n\n    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {\n        super.onCreateView(inflater, container, savedInstanceState)\n        _binding = FragmentPlacesBinding.inflate(inflater, container, false)\n\n        binding.root.setOnApplyWindowInsetsListener { view, windowInsets ->\n            val insetsCompat = WindowInsetsCompat.toWindowInsetsCompat(windowInsets, view)\n            val newStatusBarInsets = insetsCompat.getInsets(WindowInsetsCompat.Type.statusBars())\n            val newNavBarInsets = insetsCompat.getInsets(WindowInsetsCompat.Type.navigationBars())\n\n            var params = binding.controlsContainer.layoutParams as ViewGroup.MarginLayoutParams\n            params.topMargin = newStatusBarInsets.top + newNavBarInsets.top\n            params.leftMargin = newStatusBarInsets.left + newNavBarInsets.left\n            params.rightMargin = newStatusBarInsets.right + newNavBarInsets.right\n            params.bottomMargin = newStatusBarInsets.bottom + newNavBarInsets.bottom\n\n            params = binding.myLocationButton.layoutParams as ViewGroup.MarginLayoutParams\n            params.bottomMargin = newNavBarInsets.bottom + DimenUtil.roundedDpToPx(16f)\n            params.leftMargin = newStatusBarInsets.left + newNavBarInsets.left + DimenUtil.roundedDpToPx(16f)\n            params.rightMargin = newStatusBarInsets.right + newNavBarInsets.right + DimenUtil.roundedDpToPx(16f)\n            binding.myLocationButton.layoutParams = params\n\n            statusBarInsets = newStatusBarInsets\n            navBarInsets = newNavBarInsets\n            WindowInsetsCompat.Builder()\n                .setInsets(WindowInsetsCompat.Type.navigationBars(), navBarInsets!!)\n                .build().toWindowInsets() ?: windowInsets\n        }\n\n        binding.tabsButton.setOnClickListener {\n            PlacesEvent.logAction(\"tabs_view_click\", \"search_bar_view\")\n            if (WikipediaApp.instance.tabCount == 1) {\n                startActivity(PageActivity.newIntent(requireActivity()))\n            } else {\n                startActivity(TabActivity.newIntent(requireActivity()))\n            }\n        }\n\n        binding.searchTextView.setOnClickListener {\n            PlacesEvent.logAction(\"search_view_click\", \"search_bar_view\")\n            val intent = SearchActivity.newIntent(requireActivity(), Constants.InvokeSource.PLACES,\n                viewModel.highlightedPageTitle?.displayText, true)\n            val options = if (intent.component?.className == SearchActivity::class.java.name) {\n                ActivityOptionsCompat.makeSceneTransitionAnimation(requireActivity(),\n                    binding.searchContainer.getChildAt(0), getString(R.string.transition_search_bar))\n            } else null\n            placesSearchLauncher.launch(intent, options)\n        }\n\n        binding.backButton.setOnClickListener {\n            PlacesEvent.logAction(\"back_click\", \"search_bar_view\")\n            requireActivity().finish()\n        }\n\n        binding.langCodeButton.setOnClickListener {\n            PlacesEvent.logAction(\"filter_click\", \"search_bar_view\")\n            filterLauncher.launch(PlacesFilterActivity.newIntent(requireActivity()))\n        }\n\n        binding.searchCloseBtn.setOnClickListener {\n            PlacesEvent.logAction(\"search_clear_click\", \"search_bar_view\")\n            updateSearchText()\n        }\n\n        binding.myLocationButton.setOnClickListener {\n            PlacesEvent.logAction(\"current_location_click\", \"map_view\")\n            if (haveLocationPermissions()) {\n                goToLocation()\n            } else {\n                locationPermissionRequest.launch(arrayOf(Manifest.permission.ACCESS_FINE_LOCATION, Manifest.permission.ACCESS_COARSE_LOCATION))\n            }\n        }\n\n        binding.viewButtonsGroup.addOnButtonCheckedListener { _, checkedId, isChecked ->\n            if (!isChecked) {\n                return@addOnButtonCheckedListener\n            }\n            lastCheckedId = checkedId\n            val mapViewChecked = checkedId == R.id.mapViewButton\n            updateToggleViews(mapViewChecked)\n\n            val progressColor = ResourceUtil.getThemedColorStateList(requireContext(), R.attr.progressive_color)\n            val additionColor = ResourceUtil.getThemedColorStateList(requireContext(), R.attr.addition_color)\n            val placeholderColor = ResourceUtil.getThemedColorStateList(requireContext(), R.attr.placeholder_color)\n            val paperColor = ResourceUtil.getThemedColorStateList(requireContext(), R.attr.paper_color)\n            val backgroundColor = ResourceUtil.getThemedColorStateList(requireContext(), R.attr.background_color)\n            if (mapViewChecked) {\n                binding.mapViewButton.setTextColor(progressColor)\n                binding.mapViewButton.backgroundTintList = additionColor\n                binding.mapViewButton.strokeColor = paperColor\n                binding.listViewButton.setTextColor(placeholderColor)\n                binding.listViewButton.backgroundTintList = paperColor\n                binding.listViewButton.strokeColor = paperColor\n            } else {\n                binding.mapViewButton.setTextColor(placeholderColor)\n                binding.mapViewButton.backgroundTintList = backgroundColor\n                binding.mapViewButton.strokeColor = backgroundColor\n                binding.listViewButton.setTextColor(progressColor)\n                binding.listViewButton.backgroundTintList = additionColor\n                binding.listViewButton.strokeColor = backgroundColor\n            }\n        }\n\n        binding.listRecyclerView.layoutManager = LinearLayoutManager(requireContext())\n        binding.listRecyclerView.addItemDecoration(DrawableItemDecoration(requireContext(), R.attr.list_divider, drawStart = true, skipSearchBar = true))\n        binding.listEmptyMessage.text = StringUtil.fromHtml(getString(R.string.places_empty_list))\n        binding.listEmptyMessage.movementMethod = LinkMovementMethodExt { _ ->\n            binding.viewButtonsGroup.check(R.id.mapViewButton)\n        }\n\n        return binding.root\n    }\n\n    private fun updateSearchText(searchText: String = \"\") {\n        if (searchText.isEmpty()) {\n            binding.searchTextView.text = getString(R.string.places_search_hint)\n            binding.searchCloseBtn.isVisible = false\n            resetMagnifiedSymbol()\n        } else {\n            binding.searchCloseBtn.isVisible = true\n            binding.searchTextView.text = StringUtil.fromHtml(searchText)\n        }\n    }\n\n    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {\n        super.onViewCreated(view, savedInstanceState)\n        binding.mapView.onCreate(savedInstanceState)\n\n        PlacesEvent.logImpression(\"map_view\")\n\n        binding.mapView.getMapAsync { map ->\n            map.setStyle(Style.Builder().fromUri(getStyleAsset())) { style ->\n                mapboxMap = map\n\n                style.addImage(MARKER_DRAWABLE, markerBitmapBase)\n\n                map.setMaxZoomPreference(20.0)\n\n                map.uiSettings.isLogoEnabled = false\n                val defMargin = DimenUtil.roundedDpToPx(16f)\n\n                val navBarLeft = navBarInsets?.left ?: 0\n                val navBarRight = navBarInsets?.right ?: 0\n                val navBarTop = navBarInsets?.top ?: 0\n                val navBarBottom = navBarInsets?.bottom ?: 0\n                val statusBarLeft = statusBarInsets?.left ?: 0\n                val statusBarRight = statusBarInsets?.right ?: 0\n                val statusBarTop = statusBarInsets?.top ?: 0\n                val statusBarBottom = statusBarInsets?.bottom ?: 0\n\n                map.uiSettings.setCompassImage(AppCompatResources.getDrawable(requireContext(), R.drawable.ic_compass_with_bg)!!)\n                map.uiSettings.compassGravity = Gravity.TOP or Gravity.END\n                map.uiSettings.attributionGravity = Gravity.BOTTOM or Gravity.START\n                map.uiSettings.setAttributionTintColor(ResourceUtil.getThemedColor(requireContext(), R.attr.placeholder_color))\n\n                map.uiSettings.setCompassMargins(defMargin + navBarLeft + statusBarLeft,\n                    defMargin + navBarTop + statusBarTop + binding.searchContainer.height,\n                    DimenUtil.roundedDpToPx(12f) + navBarRight + statusBarRight, defMargin)\n\n                map.uiSettings.setAttributionMargins(defMargin + navBarLeft + statusBarLeft,\n                    0, defMargin + navBarRight + statusBarRight,\n                    navBarBottom + statusBarBottom + DimenUtil.roundedDpToPx(36f))\n\n                map.addOnCameraIdleListener {\n                    mapboxMap?.cameraPosition?.target?.let {\n                        onUpdateCameraPosition(it)\n                    }\n                }\n\n                map.addOnMapClickListener(this)\n\n                setUpSymbolManagerWithClustering(map, style)\n\n                symbolManager?.iconAllowOverlap = true\n                symbolManager?.textAllowOverlap = true\n                symbolManager?.addClickListener { symbol ->\n                    L.d(\">>>> clicked: \" + symbol.latLng.latitude + \", \" + symbol.latLng.longitude)\n                    PlacesEvent.logAction(\"marker_click\", \"map_view\")\n                    annotationCache.find { it.symbol == symbol }?.let {\n                        val location = Location(\"\").apply {\n                            latitude = symbol.latLng.latitude\n                            longitude = symbol.latLng.longitude\n                        }\n                        resetMagnifiedSymbol()\n                        setMagnifiedSymbol(it.symbol)\n                        viewModel.highlightedPageTitle = it.page.pageTitle\n                        symbolManager?.update(it.symbol)\n                        showLinkPreview(it.page.pageTitle, location)\n                    }\n                    true\n                }\n\n                if (haveLocationPermissions()) {\n                    startLocationTracking()\n                }\n\n                viewModel.location?.let {\n                    goToLocation(it)\n                } ?: run {\n                    if (Prefs.placesDefaultLocationLatLng != null) {\n                        goToLocation(getDefaultLocation())\n                    } else {\n                        val lastLocationAndZoomLevel = Prefs.placesLastLocationAndZoomLevel\n                        goToLocation(lastLocationAndZoomLevel?.first, lastLocationAndZoomLevel?.second ?: lastZoom)\n                    }\n\n                    if (!haveLocationPermissions()) {\n                        locationPermissionRequest.launch(arrayOf(Manifest.permission.ACCESS_FINE_LOCATION, Manifest.permission.ACCESS_COARSE_LOCATION))\n                    }\n                }\n            }\n        }\n\n        viewModel.nearbyPagesLiveData.observe(viewLifecycleOwner) {\n            if (it is Resource.Success) {\n                updateMapMarkers(it.data)\n            } else if (it is Resource.Error) {\n                FeedbackUtil.showError(requireActivity(), it.throwable)\n            }\n        }\n    }\n\n    private fun getDefaultLocation(): Location? {\n        return Prefs.placesDefaultLocationLatLng?.let { defaultLocationString ->\n            val defaultLocationStrings = defaultLocationString.split(\",\").map { it.toDouble() }\n            val defaultLocation = Location(\"\").apply {\n                latitude = defaultLocationStrings[0]\n                longitude = defaultLocationStrings[1]\n            }\n            return defaultLocation\n        }\n    }\n\n    private fun updateToggleViews(isMapVisible: Boolean) {\n        if ((binding.listRecyclerView.isVisible || binding.listEmptyContainer.isVisible) && isMapVisible) {\n            PlacesEvent.logAction(\"map_view_click\", \"map_view\")\n        }\n        if (binding.mapView.isVisible && !isMapVisible) {\n            PlacesEvent.logAction(\"list_view_click\", \"list_view\")\n        }\n        val tintColor = ResourceUtil.getThemedColorStateList(requireContext(), if (isMapVisible) R.attr.paper_color else R.attr.background_color)\n        binding.mapView.isVisible = isMapVisible\n        binding.listRecyclerView.isVisible = !isMapVisible && (binding.listRecyclerView.adapter?.itemCount ?: 0) > 0\n        binding.listEmptyContainer.isVisible = !isMapVisible && (binding.listRecyclerView.adapter?.itemCount ?: 0) == 0\n        binding.searchContainer.backgroundTintList = tintColor\n        binding.myLocationButton.isVisible = isMapVisible\n    }\n\n    private fun showLinkPreview(pageTitle: PageTitle, location: Location) {\n        PlacesEvent.logImpression(\"detail_view\")\n        val entry = HistoryEntry(pageTitle, HistoryEntry.SOURCE_PLACES)\n        updateSearchText(pageTitle.displayText)\n\n        ExclusiveBottomSheetPresenter.show(childFragmentManager,\n            LinkPreviewDialog.newInstance(entry, location, getLastKnownUserLocation()))\n    }\n\n    private fun resetMagnifiedSymbol() {\n        // Reset the magnified marker to regular size\n        magnifiedMarker?.let {\n            it.iconSize = 1.0f\n            symbolManager?.update(it)\n        }\n        viewModel.highlightedPageTitle = null\n    }\n\n    private fun setMagnifiedSymbol(symbol: Symbol?) {\n        magnifiedMarker?.symbolSortKey = 0f\n        magnifiedMarker = symbol\n        magnifiedMarker?.iconSize = 1.75f\n        magnifiedMarker?.symbolSortKey = 1f\n    }\n\n    private fun updateSearchCardViews() {\n        val tabsCount = WikipediaApp.instance.tabCount\n        binding.tabsButton.isVisible = tabsCount != 0\n        binding.tabsButton.updateTabCount(false)\n\n        if (!WikipediaApp.instance.languageState.appLanguageCodes.contains(Prefs.placesWikiCode)) {\n            Prefs.placesWikiCode = WikipediaApp.instance.appOrSystemLanguageCode\n        }\n        binding.langCodeButton.setLangCode(Prefs.placesWikiCode)\n\n        FeedbackUtil.setButtonTooltip(binding.tabsButton, binding.langCodeButton)\n    }\n\n    private fun setUpSymbolManagerWithClustering(mapboxMap: MapLibreMap, style: Style) {\n\n        symbolManager = SymbolManager(binding.mapView, mapboxMap, style, null, null, ClusterOptions())\n\n        // Clustering with SymbolManager doesn't expose a few style specifications we need.\n        // Accessing the styles in a fail-safe manner\n        try {\n            style.getLayer(CLUSTER_TEXT_LAYER_ID)?.apply {\n                this.setProperties(\n                    textField(Expression.toString(Expression.get(POINT_COUNT))),\n                    textSize(Expression.literal(22f)),\n                    textColor(ResourceUtil.getThemedColor(requireContext(), R.attr.paper_color)),\n                    textFont(CLUSTER_FONT_STACK),\n                    textIgnorePlacement(true),\n                    textAllowOverlap(true),\n                )\n            }\n            style.getLayer(CLUSTER_CIRCLE_LAYER_ID)?.apply {\n                this.setProperties(\n                    circleRadius(24f),\n                    circleColor(ContextCompat.getColor(requireActivity(), ResourceUtil.getThemedAttributeId(requireContext(), R.attr.secondary_color))),\n                    circleOpacity(0.8f),\n                    circleStrokeColor(ResourceUtil.getThemedColor(requireContext(), R.attr.paper_color)),\n                    circleStrokeWidth(2.0f),\n                )\n            }\n        } catch (e: Exception) {\n            L.e(e)\n        }\n    }\n\n    override fun onStart() {\n        super.onStart()\n        binding.mapView.onStart()\n    }\n\n    override fun onPause() {\n        super.onPause()\n        binding.mapView.onPause()\n    }\n\n    override fun onResume() {\n        super.onResume()\n        activity?.window?.let { window ->\n            WindowCompat.setDecorFitsSystemWindows(window, false)\n            window.statusBarColor = Color.TRANSPARENT\n            window.navigationBarColor = Color.TRANSPARENT\n        }\n\n        binding.mapView.onResume()\n        updateSearchCardViews()\n        updateToggleViews(lastCheckedId == R.id.mapViewButton)\n        ExclusiveBottomSheetPresenter.dismiss(childFragmentManager)\n    }\n\n    override fun onStop() {\n        super.onStop()\n        binding.mapView.onStop()\n    }\n\n    override fun onLowMemory() {\n        super.onLowMemory()\n        binding.mapView.onLowMemory()\n    }\n\n    override fun onSaveInstanceState(outState: Bundle) {\n        super.onSaveInstanceState(outState)\n        binding.mapView.onSaveInstanceState(outState)\n    }\n\n    override fun onDestroyView() {\n        lastLocation?.let {\n            Prefs.placesLastLocationAndZoomLevel = Pair(it, lastZoom)\n        }\n        binding.mapView.onDestroy()\n        _binding = null\n\n        clearAnnotationCache()\n        markerBitmapBase.recycle()\n        super.onDestroyView()\n    }\n\n    private fun clearAnnotationCache() {\n        annotationCache.clear()\n    }\n\n    private fun onUpdateCameraPosition(latLng: LatLng) {\n        lastLocation = Location(\"\").also {\n            it.latitude = latLng.latitude\n            it.longitude = latLng.longitude\n        }\n\n        lastZoom = mapboxMap?.cameraPosition?.zoom ?: 15.0\n\n        if (lastZoom < 3.0) {\n            // Don't fetch pages if the map is zoomed out too far.\n            return\n        }\n\n        // Fetch new pages within the current viewport, but only if the map has moved a significant distance.\n        val latEpsilon = (mapboxMap?.projection?.visibleRegion?.latLngBounds?.latitudeSpan ?: 0.0) * 0.2\n        val lngEpsilon = (mapboxMap?.projection?.visibleRegion?.latLngBounds?.longitudeSpan ?: 0.0) * 0.2\n        if (lastLocationQueried != null &&\n            abs(latLng.latitude - (lastLocationQueried?.latitude ?: 0.0)) < latEpsilon &&\n            abs(latLng.longitude - (lastLocationQueried?.longitude ?: 0.0)) < lngEpsilon &&\n            abs(lastZoom - lastZoomQueried) < 0.5) {\n            return\n        }\n        lastLocationQueried = lastLocation\n        lastZoomQueried = lastZoom\n\n        L.d(\">>> requesting update: \" + latLng.latitude + \", \" + latLng.longitude + \", \" + mapboxMap?.cameraPosition?.zoom)\n        viewModel.fetchNearbyPages(latLng.latitude, latLng.longitude, searchRadius, ITEMS_PER_REQUEST)\n    }\n\n    private fun updateMapMarkers(pages: List<NearbyPage>) {\n        symbolManager?.let { manager ->\n\n            pages.filter {\n                annotationCache.find { item -> item.page.pageId == it.pageId } == null\n            }.forEach {\n                val symbol = manager.create(\n                    SymbolOptions()\n                        .withLatLng(LatLng(it.latitude, it.longitude))\n                        .withTextFont(MARKER_FONT_STACK)\n                        .withIconImage(MARKER_DRAWABLE)\n                )\n                if (viewModel.highlightedPageTitle?.prefixedText.orEmpty() == it.pageTitle.prefixedText) {\n                    setMagnifiedSymbol(symbol)\n                }\n                annotationCache.addFirst(PlaceMarker(it, symbol))\n                manager.update(symbol)\n\n                queueImageForAnnotation(it)\n\n                if (annotationCache.size > MAX_ANNOTATIONS) {\n                    val removed = annotationCache.removeLast()\n                    manager.delete(removed.symbol)\n                    if (!removed.page.pageTitle.thumbUrl.isNullOrEmpty()) {\n                        mapboxMap?.style?.removeImage(removed.page.pageTitle.thumbUrl!!)\n                    }\n                }\n            }\n        }\n        binding.listRecyclerView.adapter = RecyclerViewAdapter(pages)\n\n        if (pages.isEmpty() && Prefs.placesLastLocationAndZoomLevel == null) {\n            FeedbackUtil.makeSnackbar(requireActivity(), getString(R.string.places_empty_message_snackbar)).run {\n                setAction(R.string.dialog_close_description) {\n                    dismiss()\n                }\n                show()\n            }\n            lastLocation?.let {\n                Prefs.placesLastLocationAndZoomLevel = Pair(it, lastZoom)\n            }\n        }\n    }\n\n    private fun haveLocationPermissions(): Boolean {\n        return ActivityCompat.checkSelfPermission(requireContext(), Manifest.permission.ACCESS_FINE_LOCATION) == PackageManager.PERMISSION_GRANTED &&\n                ActivityCompat.checkSelfPermission(requireContext(), Manifest.permission.ACCESS_COARSE_LOCATION) == PackageManager.PERMISSION_GRANTED\n    }\n\n    private fun getLastKnownUserLocation(): Location? {\n        return if (mapboxMap?.locationComponent?.isLocationComponentActivated == true)\n            mapboxMap?.locationComponent?.lastKnownLocation else null\n    }\n\n    @SuppressLint(\"MissingPermission\")\n    private fun startLocationTracking() {\n        mapboxMap?.let {\n            it.locationComponent.activateLocationComponent(LocationComponentActivationOptions.builder(requireContext(), it.style!!).build())\n            it.locationComponent.isLocationComponentEnabled = true\n            it.locationComponent.cameraMode = CameraMode.NONE\n            it.locationComponent.renderMode = RenderMode.COMPASS\n        }\n    }\n\n    private fun goToLocation(preferredLocation: Location? = null, zoom: Double = 15.0) {\n        binding.viewButtonsGroup.check(R.id.mapViewButton)\n        mapboxMap?.let {\n            viewModel.lastKnownLocation = getLastKnownUserLocation()\n            var currentLatLngLoc: LatLng? = null\n            viewModel.lastKnownLocation?.let { loc -> currentLatLngLoc = LatLng(loc.latitude, loc.longitude) }\n            val location = preferredLocation?.let { loc -> LatLng(loc.latitude, loc.longitude) }\n            val targetLocation = location ?: currentLatLngLoc\n            targetLocation?.let { target ->\n                it.moveCamera(CameraUpdateFactory.newLatLngZoom(target, zoom), object : CancelableCallback {\n                    override fun onCancel() { }\n\n                    override fun onFinish() {\n                        if (isAdded && preferredLocation != null && viewModel.highlightedPageTitle != null) {\n                            showLinkPreview(viewModel.highlightedPageTitle!!, preferredLocation)\n                        }\n                    }\n                })\n            }\n        }\n    }\n\n    private fun queueImageForAnnotation(page: NearbyPage) {\n        val url = page.pageTitle.thumbUrl\n        if (!Prefs.isImageDownloadEnabled || url.isNullOrEmpty()) {\n            return\n        }\n\n        ImageService.loadImage(\n            requireContext(),\n            url,\n            whiteBackground = true,\n            onSuccess = { bitmap ->\n                if (!isAdded) {\n                    return@loadImage\n                }\n                annotationCache.find { it.page.pageId == page.pageId }?.let {\n                    val bmp = getMarkerBitmap(bitmap, markerRect, markerPaintSrc, markerPaintSrcIn, markerBorderPaint)\n                    mapboxMap?.style?.addImage(url, bmp.toDrawable(resources))\n\n                    it.symbol.iconImage = url\n                    symbolManager?.update(it.symbol)\n                }\n            }\n        )\n    }\n\n    override fun onLinkPreviewLoadPage(title: PageTitle, entry: HistoryEntry, inNewTab: Boolean) {\n        if (inNewTab) {\n            TabUtil.openInNewBackgroundTab(entry)\n            requireActivity().invalidateOptionsMenu()\n            binding.tabsButton.isVisible = WikipediaApp.instance.tabCount > 0\n            binding.tabsButton.updateTabCount(true)\n        } else {\n            startActivity(PageActivity.newIntentForNewTab(requireActivity(), entry, entry.title))\n        }\n    }\n\n    override fun onLinkPreviewDismiss() {\n        updateSearchText()\n    }\n\n    override fun onMapClick(point: LatLng): Boolean {\n        mapboxMap?.let {\n            val screenPoint = it.projection.toScreenLocation(point)\n            val rect = RectF(screenPoint.x - 10, screenPoint.y - 10, screenPoint.x + 10, screenPoint.y + 10)\n\n            updateSearchText()\n            // Zoom-in 2 levels on click of a cluster circle. Do not handle other click events\n            val featureList = it.queryRenderedFeatures(rect, CLUSTER_CIRCLE_LAYER_ID)\n            if (featureList.isNotEmpty()) {\n                PlacesEvent.logAction(\"cluster_click\", \"map_view\")\n                val cameraPosition = CameraPosition.Builder()\n                    .target(point)\n                    .zoom(it.cameraPosition.zoom + 2)\n                    .build()\n                it.easeCamera(CameraUpdateFactory.newCameraPosition(cameraPosition), ZOOM_IN_ANIMATION_DURATION)\n                return true\n            }\n        }\n        return false\n    }\n\n    private class PlaceMarker(val page: NearbyPage, val symbol: Symbol)\n\n    private inner class RecyclerViewAdapter(val nearbyPages: List<NearbyPage>) : RecyclerView.Adapter<RecyclerViewItemHolder>() {\n        override fun getItemCount(): Int {\n            return nearbyPages.size\n        }\n\n        override fun onCreateViewHolder(parent: ViewGroup, type: Int): RecyclerViewItemHolder {\n            return RecyclerViewItemHolder(ItemPlacesListBinding.inflate(layoutInflater, parent, false))\n        }\n\n        override fun onBindViewHolder(holder: RecyclerViewItemHolder, position: Int) {\n            holder.bindItem(nearbyPages[position], viewModel.lastKnownLocation)\n        }\n    }\n\n    private inner class RecyclerViewItemHolder(val binding: ItemPlacesListBinding) :\n        RecyclerView.ViewHolder(binding.root), View.OnClickListener, View.OnLongClickListener {\n\n        private lateinit var page: NearbyPage\n\n        init {\n            itemView.setOnClickListener(this)\n            itemView.setOnLongClickListener(this)\n            DeviceUtil.setContextClickAsLongClick(itemView)\n        }\n\n        fun bindItem(page: NearbyPage, locationForDistance: Location?) {\n            this.page = page\n            binding.listItemTitle.text = StringUtil.fromHtml(page.pageTitle.displayText)\n            binding.listItemDescription.text = StringUtil.fromHtml(page.pageTitle.description)\n            binding.listItemDescription.isVisible = !page.pageTitle.description.isNullOrEmpty()\n            locationForDistance?.let {\n                binding.listItemDistance.text = GeoUtil.getDistanceWithUnit(it, page.location, Locale.getDefault())\n            }\n            page.pageTitle.thumbUrl?.let {\n                ViewUtil.loadImage(binding.listItemThumbnail, it)\n            }\n        }\n\n        override fun onClick(v: View) {\n            PlacesEvent.logAction(\"read_click\", \"list_view\")\n            val entry = HistoryEntry(page.pageTitle, HistoryEntry.SOURCE_PLACES)\n            startActivity(PageActivity.newIntentForNewTab(requireActivity(), entry, entry.title))\n        }\n\n        override fun onLongClick(v: View): Boolean {\n            val entry = HistoryEntry(page.pageTitle, HistoryEntry.SOURCE_PLACES)\n            val location = page.location\n            LongPressMenu(v, menuRes = R.menu.menu_places_long_press, location = location, callback = object : LongPressMenu.Callback {\n                override fun onOpenInNewTab(entry: HistoryEntry) {\n                    onLinkPreviewLoadPage(entry.title, entry, true)\n                }\n\n                override fun onSaveRequest(entry: HistoryEntry) {\n                    SaveArticleSheetDialog.show(childFragmentManager, entry.title)\n                }\n            }).show(entry)\n            return true\n        }\n    }\n\n    companion object {\n        const val MARKER_DRAWABLE = \"markerDrawable\"\n        const val POINT_COUNT = \"point_count\"\n        const val MAX_ANNOTATIONS = 250\n        const val THUMB_SIZE = 120\n        const val ITEMS_PER_REQUEST = 75\n        const val CLUSTER_TEXT_LAYER_ID = \"mapbox-android-cluster-text\"\n        const val CLUSTER_CIRCLE_LAYER_ID = \"mapbox-android-cluster-circle0\"\n        const val ZOOM_IN_ANIMATION_DURATION = 1000\n\n        val CLUSTER_FONT_STACK = arrayOf(\"Open Sans Semibold\")\n        val MARKER_FONT_STACK = arrayOf(\"Open Sans Regular\")\n        val MARKER_SIZE = DimenUtil.roundedDpToPx(40f)\n        val MARKER_BORDER_SIZE = DimenUtil.dpToPx(2f)\n\n        fun newInstance(pageTitle: PageTitle?, location: Location?): PlacesFragment {\n            return PlacesFragment().apply {\n                arguments = bundleOf(\n                    Constants.ARG_TITLE to pageTitle,\n                    PlacesActivity.EXTRA_LOCATION to location\n                )\n            }\n        }\n\n        fun getStyleAsset() = if (WikipediaApp.instance.currentTheme.isDark) \"asset://mapstyle-dark.json\" else \"asset://mapstyle.json\"\n\n        fun getMarkerRect() = Rect(0, 0, MARKER_SIZE, MARKER_SIZE)\n\n        fun getMarkerPaintSrc(context: Context) = Paint().apply {\n            isAntiAlias = true\n            color = ResourceUtil.getThemedColor(context, R.attr.secondary_color)\n            xfermode = PorterDuffXfermode(PorterDuff.Mode.SRC)\n        }\n\n        fun getMarkerPaintSrcIn() = Paint().apply {\n            isAntiAlias = true\n            xfermode = PorterDuffXfermode(PorterDuff.Mode.SRC_IN)\n        }\n\n        fun getMarkerBorderPaint(context: Context) = Paint().apply {\n            style = Paint.Style.STROKE\n            strokeWidth = MARKER_BORDER_SIZE\n            color = ResourceUtil.getThemedColor(context, R.attr.paper_color)\n            isAntiAlias = true\n        }\n\n        fun getMarkerBitmapBase(context: Context): Bitmap {\n            return createBitmap(MARKER_SIZE, MARKER_SIZE).applyCanvas {\n                val bitmap = ResourceUtil.bitmapFromVectorDrawable(context, R.drawable.ic_w_logo_circle)\n                drawMarker(this, getMarkerRect(), getMarkerPaintSrc(context), getMarkerPaintSrcIn(), getMarkerBorderPaint(context), bitmap)\n            }\n        }\n\n        /**\n         * Rough conversion of latitude degrees to meters, bounded by the limits accepted by the API.\n         */\n        fun latitudeDiffToMeters(latitudeDiff: Double): Int {\n            return (111132 * latitudeDiff).toInt().coerceIn(10, 10000)\n        }\n\n        fun getMarkerBitmap(thumbnailBitmap: Bitmap, markerRect: Rect, markerPaintSrc: Paint,\n                            markerPaintSrcIn: Paint, markerBorderPaint: Paint): Bitmap {\n            val markerSize = DimenUtil.roundedDpToPx(40f)\n            val bmp = createBitmap(markerSize, markerSize, Bitmap.Config.ARGB_8888)\n            bmp.applyCanvas {\n                this.drawColor(Color.TRANSPARENT, PorterDuff.Mode.CLEAR)\n                drawMarker(this, markerRect, markerPaintSrc, markerPaintSrcIn, markerBorderPaint, thumbnailBitmap)\n            }\n            return bmp\n        }\n\n        fun drawMarker(canvas: Canvas, markerRect: Rect, markerPaintSrc: Paint,\n                               markerPaintSrcIn: Paint, markerBorderPaint: Paint, thumbnailBitmap: Bitmap? = null) {\n            val radius = MARKER_SIZE / 2f\n            canvas.drawCircle(radius, radius, radius, markerPaintSrc)\n            thumbnailBitmap?.let {\n                val thumbnailRect = Rect(0, 0, it.width, it.height)\n                canvas.drawBitmap(it, thumbnailRect, markerRect, markerPaintSrcIn)\n            }\n            canvas.drawCircle(radius, radius, radius - MARKER_BORDER_SIZE / 2, markerBorderPaint)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/places/PlacesFragment.kt","kind":"class","line":102,"members":{"CLUSTER_CIRCLE_LAYER_ID":[805,805],"CLUSTER_FONT_STACK":[808,808],"CLUSTER_TEXT_LAYER_ID":[804,804],"ITEMS_PER_REQUEST":[803,803],"MARKER_BORDER_SIZE":[811,811],"MARKER_DRAWABLE":[799,799],"MARKER_FONT_STACK":[809,809],"MARKER_SIZE":[810,810],"MAX_ANNOTATIONS":[801,801],"POINT_COUNT":[800,800],"PlaceMarker":[736,736],"RecyclerViewAdapter":[738,750],"RecyclerViewItemHolder":[752,796],"THUMB_SIZE":[802,802],"ZOOM_IN_ANIMATION_DURATION":[806,806],"_binding":[104,104],"annotationCache":[114,114],"binding":[105,105],"clearAnnotationCache":[556,558],"drawMarker":[869,878],"filterLauncher":[159,171],"getDefaultLocation":[410,419],"getLastKnownUserLocation":[638,641],"getMarkerBitmap":[858,867],"getMarkerBitmapBase":[844,849],"getMarkerBorderPaint":[837,842],"getMarkerPaintSrc":[826,830],"getMarkerPaintSrcIn":[832,835],"getMarkerRect":[824,824],"getStyleAsset":[822,822],"goToLocation":[653,673],"haveLocationPermissions":[633,636],"lastCheckedId":[115,115],"lastLocation":[116,116],"lastLocationQueried":[117,117],"lastZoom":[118,118],"lastZoomQueried":[119,119],"latitudeDiffToMeters":[851,856],"locationPermissionRequest":[133,146],"magnifiedMarker":[131,131],"mapboxMap":[111,111],"markerBitmapBase":[121,121],"markerBorderPaint":[124,124],"markerPaintSrc":[122,122],"markerPaintSrcIn":[123,123],"markerRect":[125,125],"navBarInsets":[107,107],"newInstance":[813,820],"onCreate":[173,187],"onCreateView":[189,299],"onDestroyView":[544,554],"onLinkPreviewDismiss":[711,713],"onLinkPreviewLoadPage":[700,709],"onLowMemory":[534,537],"onMapClick":[715,734],"onPause":[510,513],"onResume":[515,527],"onSaveInstanceState":[539,542],"onStart":[505,508],"onStop":[529,532],"onUpdateCameraPosition":[560,587],"onViewCreated":[312,408],"placesSearchLauncher":[148,157],"queueImageForAnnotation":[675,698],"resetMagnifiedSymbol":[445,452],"searchRadius":[127,127],"setMagnifiedSymbol":[454,459],"setUpSymbolManagerWithClustering":[474,503],"showLinkPreview":[436,443],"startLocationTracking":[643,651],"statusBarInsets":[106,106],"symbolManager":[112,112],"updateMapMarkers":[589,631],"updateSearchCardViews":[461,472],"updateSearchText":[301,310],"updateToggleViews":[421,434],"viewModel":[109,109]},"shot":"shots/code/PlacesFragment.jpg","supers":["Fragment()","LinkPreviewDialog.LoadPageCallback","LinkPreviewDialog.DismissCallback","MapLibreMap.OnMapClickListener"]},"PlacesFragmentViewModel":{"appearsIn":[["places","h-classes","Logic \u00b7 class diagram"],["places","h-sequence","Pan the map and open a place \u00b7 sequence"]],"code":"class PlacesFragmentViewModel(savedStateHandle: SavedStateHandle) : ViewModel() {\n    val wikiSite: WikiSite get() = WikiSite.forLanguageCode(Prefs.placesWikiCode)\n    var location: Location? = savedStateHandle[PlacesActivity.EXTRA_LOCATION]\n    var highlightedPageTitle: PageTitle? = savedStateHandle[Constants.ARG_TITLE]\n\n    var lastKnownLocation: Location? = null\n    val nearbyPagesLiveData = MutableLiveData<Resource<List<NearbyPage>>>()\n\n    fun fetchNearbyPages(latitude: Double, longitude: Double, radius: Int, maxResults: Int) {\n        viewModelScope.launch(CoroutineExceptionHandler { _, throwable ->\n            nearbyPagesLiveData.postValue(Resource.Error(throwable))\n        }) {\n            val response = ServiceFactory.get(wikiSite).getGeoSearch(\"$latitude|$longitude\", radius, maxResults, maxResults)\n            val pages = response.query?.pages.orEmpty()\n                .filter { it.coordinates != null }\n                .map {\n                    NearbyPage(it.pageId, PageTitle(it.title, wikiSite,\n                        if (it.thumbUrl().isNullOrEmpty()) null else ImageUrlUtil.getUrlForPreferredSize(it.thumbUrl()!!, PlacesFragment.THUMB_SIZE),\n                        it.description, it.displayTitle(wikiSite.languageCode)), it.coordinates!![0].lat, it.coordinates[0].lon)\n                }\n                .sortedBy {\n                    lastKnownLocation?.run {\n                        it.location.distanceTo(this)\n                    }\n                }\n            nearbyPagesLiveData.postValue(Resource.Success(pages))\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/places/PlacesFragmentViewModel.kt","kind":"class","line":19,"members":{"fetchNearbyPages":[27,46],"highlightedPageTitle":[22,22],"lastKnownLocation":[24,24],"location":[21,21],"nearbyPagesLiveData":[25,25],"savedStateHandle":[19,19],"wikiSite":[20,20]},"supers":["ViewModel()"]},"ServiceFactory":{"appearsIn":[["activity","h-classes","Logic \u00b7 class diagram"],["activity","h-sequence","Open the Activity tab, logged in \u00b7 sequence"],["home","h-classes","Logic \u00b7 class diagram"],["home","h-sequence","Load more of the Community feed \u00b7 sequence"],["index","h-services","Services \u00b7 what the screens share"],["places","h-classes","Logic \u00b7 class diagram"],["places","h-sequence","Pan the map and open a place \u00b7 sequence"],["search","h-classes","Logic \u00b7 class diagram"],["search","h-sequence","Type a query \u00b7 sequence"]],"code":"object ServiceFactory {\n\n    private const val SERVICE_CACHE_SIZE = 8\n\n    private val SERVICE_CACHE = lruCache<WikiSite, Service>(SERVICE_CACHE_SIZE, create = {\n        // This method is called in the get() method if a value does not already exist.\n        createRetrofit(it, getBasePath(it)).create<Service>()\n    })\n\n    private val REST_SERVICE_CACHE = lruCache<WikiSite, RestService>(SERVICE_CACHE_SIZE, create = {\n        createRetrofit(it, getRestBasePath(it)).create<RestService>()\n    })\n\n    private val CORE_REST_SERVICE_CACHE = lruCache<WikiSite, CoreRestService>(SERVICE_CACHE_SIZE, create = {\n        createRetrofit(it, it.url() + \"/\" + CoreRestService.CORE_REST_API_PREFIX).create<CoreRestService>()\n    })\n\n    private val ANALYTICS_REST_SERVICE_CACHE = lruCache<DestinationEventService, EventService>(SERVICE_CACHE_SIZE, create = {\n        val intakeBaseUriOverride = Prefs.eventPlatformIntakeUriOverride.orEmpty().ifEmpty { it.baseUri }\n        createRetrofit(null, intakeBaseUriOverride).create<EventService>()\n    })\n\n    fun get(wiki: WikiSite): Service {\n        return SERVICE_CACHE[wiki]!!\n    }\n\n    fun getRest(wiki: WikiSite): RestService {\n        return REST_SERVICE_CACHE[wiki]!!\n    }\n\n    fun getCoreRest(wiki: WikiSite): CoreRestService {\n        return CORE_REST_SERVICE_CACHE[wiki]!!\n    }\n\n    fun getAnalyticsRest(destinationEventService: DestinationEventService): EventService {\n        return ANALYTICS_REST_SERVICE_CACHE[destinationEventService]!!\n    }\n\n    operator fun <T> get(wiki: WikiSite, baseUrl: String?, service: Class<T>): T {\n        val r = createRetrofit(wiki, baseUrl.orEmpty().ifEmpty { wiki.url() + \"/\" })\n        return r.create(service)\n    }\n\n    fun getBasePath(wiki: WikiSite): String {\n        var path = wiki.url()\n        if (!path.endsWith(\"/\")) {\n            path += \"/\"\n        }\n        return path\n    }\n\n    fun getRestBasePath(wiki: WikiSite): String {\n        var path = if (Prefs.restbaseUriFormat.isEmpty()) wiki.url() + \"/\" + RestService.REST_API_PREFIX\n        else String.format(Prefs.restbaseUriFormat, \"https\", wiki.authority())\n        if (!path.endsWith(\"/\")) {\n            path += \"/\"\n        }\n        return path\n    }\n\n    fun createRetrofit(wiki: WikiSite?, baseUrl: String, readTimeoutSec: Long = OkHttpConnectionFactory.DEFAULT_READ_TIMEOUT_SEC): Retrofit {\n        val builder = OkHttpConnectionFactory.client.newBuilder()\n        builder.readTimeout(readTimeoutSec, TimeUnit.SECONDS)\n        builder.interceptors().add(builder.interceptors().indexOfFirst { it is HttpLoggingInterceptor }, LanguageVariantHeaderInterceptor(wiki))\n\n        return Retrofit.Builder()\n            .baseUrl(baseUrl)\n            .client(builder.build())\n            .addConverterFactory(MwExceptionConverterFactory())\n            .build()\n    }\n\n    private class LanguageVariantHeaderInterceptor(private val wiki: WikiSite?) : Interceptor {\n        @Throws(IOException::class)\n        override fun intercept(chain: Interceptor.Chain): Response {\n            var request = chain.request().newBuilder()\n                .header(\"Accept-Language\", WikipediaApp.instance.getAcceptLanguage(wiki))\n                .build()\n            return chain.proceed(request)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/dataclient/ServiceFactory.kt","kind":"object","line":18,"members":{"ANALYTICS_REST_SERVICE_CACHE":[35,38],"CORE_REST_SERVICE_CACHE":[31,33],"LanguageVariantHeaderInterceptor":[90,98],"REST_SERVICE_CACHE":[27,29],"SERVICE_CACHE":[22,25],"SERVICE_CACHE_SIZE":[20,20],"createRetrofit":[78,88],"get":[40,42],"getAnalyticsRest":[52,54],"getBasePath":[61,67],"getCoreRest":[48,50],"getRest":[44,46],"getRestBasePath":[69,76]},"supers":[]}},"sourceUrl":"https://github.com/wikimedia/apps-android-wikipedia/blob/a94b2dd658c6a6bdc7f131c5bf5fa97ba9ae6bfd/"};
